<?php
declare(strict_types=1);session_start();require_once __DIR__ . '/config/product_step11.php';if(empty($_SESSION['product_data_csrf']))$_SESSION['product_data_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['product_data_csrf'];$error=null;$success=null;$products=[];$categories=[];$edit=null;$editId=isset($_GET['edit'])&&is_numeric($_GET['edit'])?(int)$_GET['edit']:0;
try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];$market=product_step11_market($pdo,$orgId);$marketId=(int)$market['id'];$tiers=product_step11_tiers($pdo,$orgId,$marketId);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'');if($action==='save_product'){$id=(int)($_POST['product_id']??0);$stock=strtoupper(trim((string)($_POST['stock']??'')));$name=trim((string)($_POST['product_name']??''));$catId=(int)($_POST['category_id']??0);$status=(string)($_POST['status']??'active');$pack=trim((string)($_POST['pack_size']??''));$unit=trim((string)($_POST['pack_unit']??''));if($stock===''||$name==='')throw new RuntimeException('Stock No. and Product Name are required.');if(!in_array($status,['active','inactive','discontinued'],true))$status='active';$code='HL-IN-'.$stock;$pdo->beginTransaction();try{if($id>0){$stmt=$pdo->prepare("UPDATE products SET category_id=?,sku=?,product_name=?,pack_size=?,pack_unit=?,status=? WHERE organization_id=? AND id=?");$stmt->execute([$catId?:null,$stock,$name,$pack===''?null:(float)$pack,$unit?:null,$status,$orgId,$id]);if($stmt->rowCount()===0){$chk=$pdo->prepare("SELECT COUNT(*) FROM products WHERE organization_id=? AND id=?");$chk->execute([$orgId,$id]);if(!(int)$chk->fetchColumn())throw new RuntimeException('Product was not found.');}}else{$stmt=$pdo->prepare("INSERT INTO products(organization_id,category_id,product_code,sku,product_name,short_name,brand_name,pack_size,pack_unit,status) VALUES(?,?,?,?,?,?, 'Herbalife',?,?,?)");$stmt->execute([$orgId,$catId?:null,$code,$stock,$name,$stock,$pack===''?null:(float)$pack,$unit?:null,$status]);$id=(int)$pdo->lastInsertId();$list=$pdo->prepare("INSERT INTO product_market_listings(organization_id,market_id,product_id,market_sku,source_reference,active_from,status) VALUES(?,?,?,?, 'Manual Product Data Center',CURDATE(),'active')");$list->execute([$orgId,$marketId,$id,$stock]);}if(business_table_exists($pdo,'audit_logs')){$a=$pdo->prepare("INSERT INTO audit_logs(organization_id,event_type,entity_type,entity_id,details_json) VALUES(?,'product_master_saved','product',?,?)");$a->execute([$orgId,$id,json_encode(['stock'=>$stock,'name'=>$name,'status'=>$status],JSON_UNESCAPED_UNICODE)]);}$pdo->commit();$success='Product master saved.';$editId=$id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
elseif($action==='add_price'){$id=(int)($_POST['product_id']??0);$date=(string)($_POST['effective_from']??'');$mrp=(float)($_POST['mrp']??0);$vp=(float)($_POST['vp']??0);if($id<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Product and valid effective date are required.');if($mrp<0||$vp<0)throw new RuntimeException('MRP and VP cannot be negative.');$stmt=$pdo->prepare("SELECT id FROM product_market_listings WHERE organization_id=? AND market_id=? AND product_id=? LIMIT 1");$stmt->execute([$orgId,$marketId,$id]);$listingId=(int)$stmt->fetchColumn();if($listingId<=0)throw new RuntimeException('India listing is missing.');$pdo->beginTransaction();try{$pdo->prepare("UPDATE product_price_versions SET effective_to=DATE_SUB(?,INTERVAL 1 DAY),status='historical' WHERE organization_id=? AND listing_id=? AND effective_from<? AND (effective_to IS NULL OR effective_to>=?)")->execute([$date,$orgId,$listingId,$date,$date]);$up=$pdo->prepare("INSERT INTO product_price_versions(organization_id,listing_id,effective_from,mrp,volume_points,currency_code,source_reference,status) VALUES(?,?,?,?,?,'INR','Manual Product Data Center','active') ON DUPLICATE KEY UPDATE mrp=VALUES(mrp),volume_points=VALUES(volume_points),source_reference=VALUES(source_reference),status='active'");$up->execute([$orgId,$listingId,$date,$mrp,$vp]);$get=$pdo->prepare("SELECT id FROM product_price_versions WHERE organization_id=? AND listing_id=? AND effective_from=? LIMIT 1");$get->execute([$orgId,$listingId,$date]);$priceId=(int)$get->fetchColumn();$tp=$pdo->prepare("INSERT INTO product_tier_prices(price_version_id,discount_tier_id,price_amount,pricing_method) VALUES(?,?,?,'manual_exact') ON DUPLICATE KEY UPDATE price_amount=VALUES(price_amount),pricing_method='manual_exact'");foreach($tiers as $code=>$t){$key='tier_'.$code;if(isset($_POST[$key])&&trim((string)$_POST[$key])!=='')$tp->execute([$priceId,(int)$t['id'],(float)$_POST[$key]]);}if(business_table_exists($pdo,'audit_logs')){$a=$pdo->prepare("INSERT INTO audit_logs(organization_id,event_type,entity_type,entity_id,details_json) VALUES(?,'product_price_version_saved','product',?,?)");$a->execute([$orgId,$id,json_encode(['effective_from'=>$date,'mrp'=>$mrp,'vp'=>$vp])]);}$pdo->commit();$success='New price version saved and older active period closed safely.';$editId=$id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
}
$stmt=$pdo->prepare("SELECT id,category_name FROM product_categories WHERE organization_id=? AND status='active' ORDER BY sort_order,category_name");$stmt->execute([$orgId]);$categories=$stmt->fetchAll();$stmt=$pdo->prepare("SELECT p.id,p.sku,p.product_name,p.status,c.category_name FROM products p LEFT JOIN product_categories c ON c.id=p.category_id WHERE p.organization_id=? ORDER BY p.product_name");$stmt->execute([$orgId]);$products=$stmt->fetchAll();if($editId>0){$stmt=$pdo->prepare("SELECT p.*,l.id listing_id,pv.id price_id,pv.effective_from,pv.mrp,pv.volume_points FROM products p LEFT JOIN product_market_listings l ON l.product_id=p.id AND l.organization_id=p.organization_id LEFT JOIN product_price_versions pv ON pv.id=(SELECT pv2.id FROM product_price_versions pv2 WHERE pv2.organization_id=p.organization_id AND pv2.listing_id=l.id ORDER BY pv2.effective_from DESC,pv2.id DESC LIMIT 1) WHERE p.organization_id=? AND p.id=? LIMIT 1");$stmt->execute([$orgId,$editId]);$edit=$stmt->fetch()?:null;}}catch(Throwable $e){$error=$e->getMessage();}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Product Data Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="product_catalog.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>Product & Price Pro • Data Center</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_seed.php">PDF Seed</a><a class="os-btn" href="product_price_history.php">Price History</a><a class="os-btn primary" href="product_catalog.php">Catalog</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Product System</div><nav class="os-nav"><a href="product_catalog.php"><i class="dot"></i>Catalog</a><a class="active" href="product_data_center.php"><i class="dot"></i>Data Center</a><a href="product_images.php"><i class="dot"></i>Images</a><a href="product_price_history.php"><i class="dot"></i>Price History</a><a href="product_import_center.php"><i class="dot"></i>PDF Import</a></nav><div class="os-sidebar-status"><b>No hard delete</b><span>Products become inactive/discontinued. New price dates create versions rather than erasing history.</span></div></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 11 • Product Data Center</div><h1>Safely maintain product master data and future dated price versions.</h1><p>Use this for genuine manual corrections or new items. PDF-seeded April 2026 pricing stays source-traceable and price history remains preserved.</p></section><?php if($success):?><div class="pp-alert good"><?= product_h($success) ?></div><?php endif;?><?php if($error):?><div class="pp-alert bad"><?= product_h($error) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid"><article class="os-card pp-span-7"><div class="os-title-row"><div><h2>Product Master</h2><p>Select Edit below, or leave Product ID blank to create a new product.</p></div></div><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="product_id" value="<?= (int)($edit['id']??0) ?>"><label>Stock No.<input name="stock" required value="<?= product_h($edit['sku']??'') ?>"></label><label>Product Name<input name="product_name" required value="<?= product_h($edit['product_name']??'') ?>"></label><label>Category<select name="category_id"><option value="0">Uncategorised</option><?php foreach($categories as $c):?><option value="<?= (int)$c['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= product_h($c['category_name']) ?></option><?php endforeach;?></select></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><label>Pack Size<input type="number" step="0.001" min="0" name="pack_size" value="<?= product_h($edit['pack_size']??'') ?>"></label><label>Pack Unit<input name="pack_unit" value="<?= product_h($edit['pack_unit']??'') ?>" placeholder="g / ml / tablets"></label></div><label>Status<select name="status"><?php foreach(['active','inactive','discontinued'] as $s):?><option <?= ($edit['status']??'active')===$s?'selected':'' ?>><?= product_h($s) ?></option><?php endforeach;?></select></label><button><?= $edit?'Update Product':'Create Product' ?></button></form></article><aside class="os-card pp-span-5"><h2>New Price Version</h2><?php if(!$edit):?><p>Select a product from the list below before adding a price version.</p><?php else:?><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="action" value="add_price"><input type="hidden" name="product_id" value="<?= (int)$edit['id'] ?>"><label>Effective From<input type="date" name="effective_from" required value="<?= product_h(date('Y-m-d')) ?>"></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><label>MRP<input type="number" min="0" step="0.01" name="mrp" required value="<?= product_h($edit['mrp']??0) ?>"></label><label>VP<input type="number" min="0" step="0.001" name="vp" required value="<?= product_h($edit['volume_points']??0) ?>"></label></div><?php foreach($tiers as $code=>$t):?><label><?= product_h($t['tier_name']) ?><input type="number" min="0" step="0.01" name="tier_<?= product_h($code) ?>" placeholder="Leave blank if source has no price"></label><?php endforeach;?><button>Save Dated Price Version</button></form><?php endif;?></aside><article class="os-card pp-span-12"><h2>Products</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Stock</th><th>Product</th><th>Category</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><b><?= product_h($p['sku']) ?></b></td><td><?= product_h($p['product_name']) ?></td><td><?= product_h($p['category_name']) ?></td><td><?= product_h($p['status']) ?></td><td><a class="pp-badge" href="?edit=<?= (int)$p['id'] ?>">Edit / Add Price</a></td></tr><?php endforeach;?></tbody></table></div></article></section><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
